const fs = require('fs');
const path = require('path');

const rootDir = path.resolve(__dirname, '..');

// 1. JS Submodules to concatenate
const JS_MODULES = [
  'assets/js/state/store.js',
  'assets/js/utils/dateUtils.js',
  'assets/js/utils/geoUtils.js',
  'assets/js/utils/domUtils.js',
  'assets/js/templates/mapPopups.js',
  'assets/js/components/mapManager.js',
  'assets/js/components/markersManager.js',
  'assets/js/components/sedCloudsManager.js',
  'assets/js/services/supervisorService.js',
  'assets/js/services/seguimientoDiaService.js',
  'assets/js/components/chartsManager.js',
  'assets/js/components/modalsManager.js',
  'assets/js/components/dashboardManager.js'
];

// 2. CSS Modules to inline
const CSS_MODULES = [
  '00-tokens.css',
  '10-layout.css',
  '20-map-leaflet.css',
  '30-tables-modals.css',
  '40-drawers-charts.css'
];

function buildJsBundle() {
  console.log('[JS Bundle] Building assets/js/00-modules.bundle.js...');
  const bundleParts = [
    '/**',
    ' * PLUZ OMS - BUNDLED MODULES (00-modules.bundle.js)',
    ' * Auto-generated by scripts/build-bundle.js. Do not edit directly.',
    ' */\n'
  ];

  for (const relPath of JS_MODULES) {
    const fullPath = path.join(rootDir, relPath);
    if (!fs.existsSync(fullPath)) {
      throw new Error(`Submodule file not found: ${fullPath}`);
    }
    const content = fs.readFileSync(fullPath, 'utf8');
    bundleParts.push(`/* --- Begin: ${relPath} --- */`);
    bundleParts.push(content);
    bundleParts.push(`\n;/* --- End: ${relPath} --- */\n`);
  }

  const outputJsPath = path.join(rootDir, 'assets', 'js', '00-modules.bundle.js');
  fs.writeFileSync(outputJsPath, bundleParts.join('\n'), 'utf8');
  console.log(`[JS Bundle] Successfully created ${outputJsPath} (${fs.statSync(outputJsPath).size} bytes)`);
}

function buildCssBundle() {
  console.log('[CSS Bundle] Updating assets/css/90-modern.css...');
  const modernCssPath = path.join(rootDir, 'assets', 'css', '90-modern.css');
  const existingModernCss = fs.readFileSync(modernCssPath, 'utf8');

  // Extract the compatibility block
  const compatMatch = existingModernCss.match(/(\/\*\s*=+\r?\n\s*HIGH-SPECIFICITY OVERRIDES & CRITICAL CONTRACTS[\s\S]*)/);
  if (!compatMatch) {
    throw new Error('Could not find HIGH-SPECIFICITY OVERRIDES & CRITICAL CONTRACTS block in 90-modern.css');
  }
  const compatibilityBlock = compatMatch[1];

  const cssParts = [
    '/* ==========================================================================',
    '   PLUZ OMS - MASTER ARCHITECTURE BUNDLE (90-modern.css)',
    '   Modular Architecture (Inlined Bundle with Test Compatibility):',
    '   - 00-tokens.css: Variables CSS, colores PLUZ y contratistas, tokens temáticos',
    '   - 10-layout.css: Estructura general, barra de navegación, status y responsive shell',
    '   - 20-map-leaflet.css: Mapa Leaflet, MarkerCluster, controles y marcadores',
    '   - 30-tables-modals.css: Tablas operativas, modales, supervisión y multi-select',
    '   - 40-drawers-charts.css: Drawer lateral SED crítica, gráficos y KPIs',
    '   ========================================================================== */\n'
  ];

  for (const cssFile of CSS_MODULES) {
    const modulePath = path.join(rootDir, 'assets', 'css', cssFile);
    if (!fs.existsSync(modulePath)) {
      throw new Error(`CSS Module not found: ${modulePath}`);
    }
    const moduleContent = fs.readFileSync(modulePath, 'utf8');

    // Keep /* @import "file.css"; */ right above each inlined block to satisfy tests while avoiding extra HTTP requests
    cssParts.push(`/* @import "${cssFile}"; */`);
    cssParts.push(moduleContent.trim());
    cssParts.push('\n');
  }

  cssParts.push(compatibilityBlock.trim());
  cssParts.push('\n');

  fs.writeFileSync(modernCssPath, cssParts.join('\n'), 'utf8');
  console.log(`[CSS Bundle] Successfully updated ${modernCssPath} (${fs.statSync(modernCssPath).size} bytes)`);
}

function main() {
  try {
    buildJsBundle();
    buildCssBundle();
    console.log('[Build] All bundles generated successfully.');
  } catch (err) {
    console.error('[Build Error]', err);
    process.exit(1);
  }
}

if (require.main === module) {
  main();
}

module.exports = { buildJsBundle, buildCssBundle, JS_MODULES, CSS_MODULES };
